The invariant is that `count` stays between 0 and 17, `head` identifies the next item to pop, and `tail == (head + count) % 17`. Items are popped in insertion order; a full push or empty pop leaves the queue unchanged. The count distinguishes full from empty even when `head == tail`.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

void check(bool condition) {
    if (!condition) throw std::runtime_error("Test failed");
}

int main() {
    BoundedFIFO queue;
    check(!queue.pop().has_value());

    // Fill, reject overflow, and drain in FIFO order.
    for (int i = 0; i < 17; ++i) check(queue.push(i));
    check(queue.size() == 17);
    check(!queue.push(999));
    check(queue.size() == 17);
    for (int i = 0; i < 17; ++i) check(queue.pop() == i);
    check(queue.size() == 0);
    check(!queue.pop().has_value());

    // Retain five items, then wrap the tail around the array.
    for (int i = 100; i <= 111; ++i) check(queue.push(i));
    for (int i = 100; i <= 106; ++i) check(queue.pop() == i);
    check(queue.size() == 5);
    for (int i = 112; i <= 123; ++i) check(queue.push(i));
    check(queue.size() == 17);
    check(!queue.push(999));

    // Drain across the array boundary, checking preserved order.
    for (int i = 107; i <= 123; ++i) check(queue.pop() == i);
    check(queue.size() == 0);
    check(!queue.pop().has_value());

    std::cout << "All tests passed\n";
}
```

Save as `fifo.cpp`, compile with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo`, then run the executable. This implementation assumes single-threaded access.
